import { eventContextPaths } from './event-context';

// These words are contextual beneath a handler, never global property keywords.
export const handlerIntentDocs = {
    implementation: 'Handler-only intent with ordered hints and at most one file or tagged fence. No payload means pending. Handler execution is unsupported; this is not confirmation.',
    hint: 'One nonblank quoted implementation hint. Order and decoded text are retained; hints do not execute or confirm code.',
};

export const keywordDocs: Record<string, string> = {
    agents: '**agents** declares an explicit application allowlist for AI agents. Use `tokens personal`, qualified `command` / `query` targets, a non-empty `description` and `scope read` or `scope write` (commands require write). Existing module, feature and operation authorization still applies. Global scopes, approval directives, ungated operations and unsupported query shapes are refused. Only keyed, single-result, non-observable queries are admitted. Authoring-only: executable-model binding reports PLAY0268 (#1165); no token issuance or authentication protocol is defined.',
    item: 'One element of a structured list, one per line: `item <value>` for a scalar, a bare `item` with an indented block for an object or nested list, `item none` for an empty list and `item empty` for an object without members. Also a navigation or toolbar entry. Screenplay has no JSON.',
    none: 'States an empty list in a structured value: `<name> none`. Elsewhere, an explicit empty choice such as `operations none`.',
    parameter: 'A typed value declared by a specification table, or an argument of a named behavior. Table types are required; every case supplies each parameter exactly once.',
    case: 'One named concrete row of a specification table, expanded as <Specification>_<Case>. Use case.<parameter> for a whole step value.',
    example: 'One typed, possibly partial fixture: `example <Name> : <EventOrCommandOrReadModel>`. Use its name in a matching specification step; assignments override example values without changing matching or supplying defaults. Event examples may carry stream or no stream; a step replaces that route as a whole.',
    domain: 'The domain the file belongs to — optional, at most one per file, before everything else.',
    import: 'Imports a type from another module by its qualified name — `import Module.Type` — making it available by its short name; or, quoted, other `.play` files by path or glob — `import "Orders/**/*.play"`, relative to this file\'s folder. Written inside a module or feature, a file import places the imported files there: their top level is that module\'s or feature\'s body. `import Module.Event from "origin"` is instead public contract metadata with an opaque origin; executable binding refuses it with PLAY0268.',
    concept: 'A formalized value type wrapping a primitive. Bare pii and secret markers travel with every usage, with optional concept notes and qualifiers.',
    type: 'A top-level composite value type — a named shape built from several properties, referenced by events, commands, read-model members and other types the same way a concept is. A slice-local type is skipped with PLAY0029; an unsupported read-model member type is Error PLAY0273. Use a top-level type for reusable child shapes, not another read-model identity.',
    reason: 'A free-text concept note, not a lawful basis. Written as pii reason "..." or secret reason "..."; migration preserves it verbatim.',
    optional: 'Allows a value to be absent. Write it after the type: `note String optional` or `lines InvoiceLine[] optional`. The collection itself may be absent; its items keep their declared type.',
    identifier: 'Marks the command property a runtime resolves the event source id from. At most one per command; without it a new Uuid is generated.',
    policy: 'A named authorization rule referenced by commands and queries. Multiple policies AND together.',
    provide: 'Declares a named value that `$context.<name>` carries for everything beneath this level (application, module, feature or slice). The nearest declaration wins; an override must keep the type. It reads from a query (`from query Q by ...`), a literal, `$context`, `$identity` or template value, or the host (`from host`). Host, code and file sources are opaque: the model never evaluates them. A preview construct (#1300), not yet admitted by any ESM version.',
    purpose: 'A report-only processing declaration (GDPR Art. 30), referenced on modules, features and slices. Coverage is their union, not an authorization gate. Generated declarations are not legal advice.',
    basis: 'One declared Art. 6(1) basis: consent, contract, legalObligation, vitalInterests, publicTask or legitimateInterests; an optional quoted reference may follow.',
    interest: 'The legitimate-interest statement for basis legitimateInterests (Art. 13(1)(d)).',
    condition: 'One Art. 9(2) processing condition, optionally followed by a quoted reference.',
    subjects: 'Comma-separated categories of data subjects, as open identifiers.',
    retention: 'Declared retention period or criteria, not enforced by the model or Chronicle.',
    recipient: 'A quoted recipient category; repeatable on a purpose.',
    transfer: 'A declared destination followed by safeguard and quoted safeguards; repeatable.',
    safeguard: 'The declared safeguard accompanying a third-country transfer.',
    erasure: 'An erasure exception under Art. 17(3); Chronicle crypto-shredding remains per subject, not per purpose.',
    exception: 'One declared Art. 17(3) exception: expression, legalObligation, publicTask, publicHealth, archiving or legalClaims.',
    persona: 'A named role interacting with the application, with an optional description, goals, its associated policies and, on the personas canvas, a position and size.',
    user: '`user <name> ["<display name>"] [as <Persona>, ...]` declares a person a development or test session can act as; the roles come from the personas it plays. Authoring metadata for development tooling, never part of the executable model.',
    storyline: '`storyline <Name> ["<title>"]` names an ordered path through the model, such as a user journey. Each step is `<kind> <reference> ["<note>"]` with kind module, feature, slice, command, event, readmodel, query, screen or reaction; renames and moves rewrite the steps. Authoring metadata, never part of the executable model.',
    sticky: '`sticky note on personas|eventsources|givencontexts|seeddata` places a free-standing note (description, optional colour yellow/pink/green/blue, position, size) on that domain canvas. Authoring metadata only; never part of the executable model.',
    goal: 'What a persona is trying to achieve, as a quoted line; repeatable. Authoring metadata only.',
    colour: 'The colour of a sticky note: yellow, pink, green or blue.',
    size: 'How big a persona or sticky note is on its canvas: `size <width> <height>` in whole canvas units.',
    position: 'Where a persona, event source or sticky note sits on its canvas: `position <x> <y>` in whole canvas units.',
    context: 'Declares named application context inputs: `context` with `<name> time zone` members (decision 0132). At most one application-root block; optional description. ESM v37 admits calendar from $context.timeZone or a member declared in the context block; other context paths remain refused. No defaults, values, sources or optional modifiers.',
    identity: 'Declares typed additional caller details from a claim, a keyed single-result query, inline code or a file. Authoring metadata only; executable use of `$identity.<detail>` reports PLAY0268 until admitted (#600).',
    authentication: 'Declares the identity providers of the application — at most one block per file.',
    provider: 'An identity provider within `authentication`: `provider <Kind>` or `provider <Kind> name <Alias>`. How to reach it is configured where the application runs, never in the model.',
    onboarding: 'Declares how people get into the application: self-signup, invitations, legal terms, an offering and the emails sent. Needs `authentication`; at most one block per application. Authoring metadata only; the sender and mail server are environment values.',
    signup: '`signup open creates tenant` or `signup open joins tenant` turns self-signup on. Without it, nobody can sign themselves up.',
    invite: '`invite tenant as <Persona>` invites someone to create a tenant, or `invite member` with `by <Persona>, ...` and `grant <Persona>, ...` invites someone into an existing one. Personas must be declared.',
    grant: 'In `invite member`, the personas an invitation gives the invitee: `grant <Persona>, ...`.',
    legal: '`legal terms` lists the documents a newcomer must accept, each as `file <path>` relative to the repository root.',
    offering: '`offering <Name>` names the offering a new tenant starts on. The name is opaque to the model.',
    emails: 'Names a template file per onboarding email (`invitation`, `welcome`, `signupDeclined`) and an `images` folder. The sender and mail server are environment values.',
    images: 'In `emails`, `images <folder>` is the folder, relative to the repository root, holding the images the templates use.',
    description: 'A human-readable description, including the rule or case a specification witnesses, as a quoted single line or a fenced ```text block for multiple lines.',
    depends: 'Declares `depends on <Name>` on a module or feature. This opts only that container into checking counted explicit references against its own declarations; it does not change executable bytes.',
    module: 'The top-level namespace — maps to a bounded context.',
    layout: 'A reusable screen template with named slots.',
    template: 'Names a template to fill or assign: `template <Name>` for an own template, `template blueprint <Blueprint> <Name> [version "<range>"]` for a template a blueprint package ships.',
    blueprint: 'In `template blueprint <Blueprint> <Name>`, the blueprint package the template comes from. A `ui profile` should list it under `packages`. In `ui profile` `sample data`, `active blueprint <id>` selects a sample data pack a blueprint ships, resolved by the build against its packages.',
    version: 'In `template blueprint ... version "<range>"`, the semver range of the blueprint the reference accepts, such as `^1.4`.',
    scopes: 'Where a template may be used: `application`, `module`, `feature`, `subfeature` or `slice`. `slice` can be followed by the kinds `statechange` and `stateview`, such as `scopes slice statechange|stateview`.',
    category: 'The group a template picker lists a layout or template under. Every layout and template needs one.',
    feature: 'A vertical slice grouping. Features nest arbitrarily deep.',
    slice: 'The atomic unit of behavior, aligned with Event Modeling. Has a type and a name.',
    public: 'Marks an event as a public contract. An event with from "origin" is also public. Origin is opaque, not a path or declaration reference. Public events and origins are admitted by executable semantic model (ESM) v9.',
    direction: 'Declare direction inbound or direction outbound once inside a Translate slice. Admitted by executable semantic model (ESM) v9; a Translate slice that uses public events must declare it (PLAY0614).',
    inbound: 'Inbound Translate direction metadata. No transport or delivery guarantee is implied.',
    outbound: 'Outbound Translate direction metadata. No transport or delivery guarantee is implied.',
    event: 'An immutable, past-tense fact. Declare it in a slice or inline with `produces event <Name>` in a command. Inline properties are typed mappings; inline tags belong to the event type.',
    documentation: 'Authoring-only reasoning on a module, feature, slice, command, event, read model or reaction in one nonempty fenced ```markdown block. It does not change executable model bytes.',
    id: 'Preserves the previous persisted event name after a rename. Leave absent on new events; repeating the current name is redundant.',
    command: 'An imperative intent. Declares authorization, validation, and what events it produces — declaratively, or via a full handler.',
    query: 'A read-side entry point mapping to a return type, with an optional description, parameters and performer. The by key and every supplied filter value satisfy their concept rules after authorization; violations reject with Validation, not an empty result.',
    sink: 'A logical store for read models or graphs, mapped to storage by the deployment.',
    passive: 'Opts a read model into replay on demand for command decisions instead of materialization. Bare readmodel body directive, default active and never inferred. Only commands may read a passive model; queries and screens are rejected (PLAY0859), and an unused passive model warns (PLAY0860). Realization metadata, not portable ESM.',
    observable: 'Qualifies a query return type as a live read — `query <Name> => observable <ReadModel>` keeps pushing as the read model changes, instead of answering once.',
    performer: 'The code that performs a query — a `file <Path>` reference or an inline `csharp`/`sql` block. The query\'s counterpart to a command handler.',
    from: 'On a reaction or reducer, `from Source[.Stream]` observes only matching routed facts. It does not filter stream ids. Admitted by ESM v10. On a query parameter, fills it from the query context instead of the caller, as in `filter tenantId TenantId from $context.tenant`.',
    projection: 'Declares how events project into a read model, using the embedded Projection Declaration Language (PDL).',
    capture: 'Converts external data into events, using the embedded Change Data Capture Language (CDL).',
    protected: 'Application-root `command reads protected` admits eligible command reads (ESM v25). Required absence rejects with Validation before derive/provide and requirements; a matching intervening fact yields Conflict/DecisionStateChanged without facts. Without the preamble, legacy reads retain their existing refusals. Targets must separately admit the version.',
    batches: 'Application-root `reaction batches atomic` opts into ESM v22 atomic direct and refusal-branch batches. Invoked commands remain separate transactions.',
    atomic: 'All productions in one reaction trigger occurrence or selected refusal branch are adopted together or not at all. Absence retains legacy per-fact semantics.',
    reaction: 'Behavior that runs when something happens. Lives inside Automation slices. A trigger with no body states intent on its own — `file`/code is optional realization metadata.',
    statemachine: '`statemachine <Name>` declares where a thing is in its lifecycle, derived from the read model it `follows` (ESM v36). A state allows the targets of the transitions written under it; an event takes the first transition on it whose condition holds and whose target the current state allows, and is otherwise ignored.',
    follows: '`follows <ReadModel>` names the read model a state machine follows; its key identifies one instance.',
    compute: 'A workflow node that computes values in C# and returns named fields later nodes read as `Node.field`: `compute <Name>` with `returns`, a C# body and `next ->`.',
    returned: '`on returned` is the branch an invocation takes when the ability answers normally; read `$result.<field>`. `on failed` handles failure (`$failure.reason`); `on <Outcome>` handles a declared outcome (`$outcome.<field>`).',
    entering: '`entering invokes <Command>` or `entering starts <Workflow>` says what entering a state does. It may run again on redelivery, so it must be safe to repeat.',
    workflow: '`workflow <Name>` declares a durable process (ESM v36): nodes with named outlets joined by edges, one run at a time per subject (`for <ReadModel>`). An unconnected `failed`, `rejected` or `expired` outlet fails the run; any other unconnected outlet ends the branch.',
    decide: '`decide <Name> when <condition>` chooses between exactly two outlets of your own: the first is taken when the condition over the subject holds.',
    approval: '`approval <Name> by <Persona or Policy> [expires after <n> <unit>]` waits for a person. Outlets: approved, rejected, expired.',
    foreach: '`foreach <Name> over <property> [parallel <n>]` runs the `each` branch once per item of a collection property of the subject, then takes `completed`.',
    runs: '`runs as system [role "Role" and role "Role"]` declares the identity for every returned or invoked command of a reaction, not imperative pipeline calls. Admitted by released ESM v10; claims are unknown for this identity. Clock and application triggers have no Stage realization yet.',
    trigger: 'Declares a kind of occurrence a reaction can respond to, and the values it hands the reaction. What makes one occur belongs to whoever provides it, never to the compiler.',
    where: 'Narrows which occurrences actually run the reaction.',
    contains: 'Ordinal UTF-16 text comparison: the value holds the literal operand anywhere. In validation, `not contains` negates it; absent optional values pass. An empty operand always occurs.',
    starts: 'Use `starts with "text"` for an ordinal UTF-16 literal prefix validation rule or condition.',
    ends: 'Use `ends with "text"` for an ordinal UTF-16 literal suffix validation rule. An absent optional value passes.',
    every: 'Runs a reaction on an interval — `every 15 minutes`, `every 1 day`.',
    refused: 'Ordered invocation refusal branch, executable from ESM v19: first match wins and stops remaining invocations of this trigger. Bare `on refused` covers validation and constraints, not authorization. Other reactions and cascades continue; contract errors, concurrency and Unsupported never match.',
    acknowledge: 'A refusal branch acknowledges alone without facts, or produces events instead. Executable from ESM v19; handling stops remaining invocations of this trigger.',
    validation: 'In `on refused by validation`, selects error-severity property, concept and require refusals. Executable from ESM v19.',
    authorization: 'In `on refused by authorization`, explicitly selects unauthorized results, never Unsupported. Executable from ESM v19; bare refusal excludes authorization.',
    redelivered: '`when redelivered <Event> to <Reaction>` selects exactly one effective given occurrence by optional for, stated values and stream or no stream, delivering that event again to one named reaction without appending it again. Executable from ESM v17.',
    invokes: 'A command handed on to run: `then invokes <Command>` in a reaction, `action <Node> invokes <Command>` in a workflow, `entering invokes <Command>` in a state machine and `then invokes <Command>` in a lifecycle specification. A command is asked for, not produced — it may still be refused; a workflow action takes its `refused` outlet then. Replaces `sends` and `entering send`.',
    screen: 'A UI declaration. Supports intent, structure, and layout-with-code levels, or a full file reference.',
    constraint: 'A server-side rule enforced in the Chronicle kernel before events are committed.',
    authorize: 'References the policies that must all pass for the construct to execute.',
    validate: 'Declarative validation rules, or `validate` followed by a ```csharp fence or `file <path>` for imperative rules — on commands and concepts.',
    checksum: 'String-concept validation: exact trailing luhn/mod11 digit or two mod97 digits over preceding ASCII digits. Also applies to supplied and stored values; generation does not silently add validation.',
    luhn: 'Luhn check digit, with standard parity from the right. Generation appends it; validate checksum luhn checks the arithmetic.',
    mod11: 'Check digit (11 - weighted sum modulo 11) modulo 11, weights 2..7 cycling from the right. Output 10 is excluded from generation support.',
    mod97: 'ISO 7064 MOD 97-10, two zero-padded trailing digits. Validation checks the exact computed suffix, not only congruence.',
    produces: 'References a declared event with `produces <Name>`, or declares one inline with `produces event <Name>`. An inline omitted `for` uses the command identifier only when all destinations are the same source; legacy plain omission allocates an identity.',
    reads: 'Declares a view consulted by a command or reaction trigger: `reads <View> [as <alias>] [by <value>]`. A reaction `by` names a value taken by its trigger; clock triggers cannot use `by`. A child by block supplies composite key parts by name, using part = source, but is refused for protected command reads (PLAY0781 ByParts). Repeated views require unique aliases. With `command reads protected`, command reads bind only over finite event-log projections keyed by event-source identity with removal handlers and required scalar non-generated input keys. Omitted `by` uses the command identifier. Single-level read/alias.property paths are admitted in validate require operands and produces mappings only. Reaction reads remain unadmitted.',
    as: 'Names an instance of a view in a command or reaction trigger reads declaration, for example `reads Account as source by sourceId`.',
    handler: 'A fully imperative command implementation — a `file <Path>` reference or an inline `csharp` block, instead of `produces`.',
    when: 'Guards a produced event or a capture append with a condition. In a labeled screen action, `when item.<field> == <literal> execute <Command>` selects the first matching command. Inside on click, double click, select or change, block-form `when <condition>` selects one whole action list at gesture time.',
    rule: 'Names a predicate. Bare, it states that a constraint exists without expressing what it computes — nothing resolves the name. Optionally followed by an indented `file <Path>` reference or inline `csharp` block giving it a body.',
    require: 'A policy condition: `authenticated`, `anonymous`, `role "..."`, or `claim "..." matches ...`. Unary `not` negates a condition or group; precedence is not, and, or.',
    authenticated: 'Requires an authenticated caller.',
    anonymous: 'Admits every caller, including one without an identity (ESM v31). Stands alone in `require` and is the whole authorization of what it gates; its specifications may omit `given caller`.',
    role: 'Requires the caller to have the given role.',
    claim: 'Requires a claim on the caller to match a subject or value.',
    subject: 'In policy `matches subject`, the identifier of the thing acted on, not the caller. The caller is `$context.causedBy.subject`.',
    data: 'Binds a read model to a screen through a query.',
    action: 'Makes a command available on a screen. `action "Label"` declares one button with ordered `when … execute` alternatives over the nearest data item or selected row. No subject hides it; commands still enforce authorization and validation.',
    otherwise: 'The final fallback of a guarded action: `otherwise hidden` or `otherwise execute <Command>`. In an item interaction, bare `otherwise` opens a fallback action list. No subject runs nothing, including fallback; authorization never falls through.',
    hidden: 'Hides a guarded action when no condition matches. Without a subject the action is always hidden, even with an execute fallback.',
    execute: 'Executes a command. A guarded screen action selects it by the first matching condition; explicit `with … from` bindings precede same-name item fields, its declared form and renderer input.',
    navigate: 'Navigates to a screen, optionally passing a parameter with `by`.',
    section: 'A named structural section of a screen.',
    table: 'A table widget over a read model or child collection.',
    summary: 'A summary widget showing labeled fields.',
    column: 'A table column bound to a property.',
    field: 'A summary field bound to a property.',
    title: 'The display title of a screen or section.',
    label: 'The display label of an action, column, or field.',
    unique: 'A uniqueness constraint — `unique <property> on <EventType>` or `unique event <EventType>`.',
    concurrency: 'The concurrency scope enforced when the command appends events — dimensions: `eventSource`, `sourceType`, `streamType`, `streamId`, `events`.',
    eventSource: 'Concurrency dimension — scope the check to the event source id of the command.',
    sourceType: 'Concurrency dimension — scope the check to an event source type.',
    streamType: 'Concurrency dimension — scope the check to an event stream type.',
    streamId: 'Concurrency dimension — scope the check to an event stream id.',
    tag: 'Attaches a tag to appended events — a static identifier or string, or a `$context.` expression resolved at append time.',
    seed: 'Declares events to seed into the event store per event source id — multiple blocks accumulate.',
    for: 'Names the event source of a production or seed group. Inside `produces event`, omission uses the command identifier unless another production targets a different source.',
    readmodel: 'Declares a read model — its name and properties — in a slice, or, in a specification, read model state: `given readmodel` establishes it, `then readmodel` asserts it, `then no readmodel <View> for <key>` asserts keyed absence. Members use primitives, concepts, top-level composite types or imported value-type names; another read model is an identity, not a reusable member type (PLAY0273).',
    graph: 'Declares the shape of a property graph — `node <Label>` with typed properties (exactly one `key`) and `edge <TYPE> source <Label> target <Label>`; in a specification, `given graph` seeds it and `then graph` asserts nodes and edges. A `projection <Name> => graph <Graph>` builds it from events.',
    node: "In a graph, declares a node label with its properties; in a graph projection, `node <Label>` opens how events create, change and remove that node; in a specification `has node` and `no node` assert one.",
    edge: "In a graph, declares an edge type between two node labels (`edge <TYPE> source <Label> target <Label>`); in a graph projection, `edge <TYPE>` opens how events create, change and remove that edge; in a specification `has edge` and `no edge` assert one.",
    detach: 'On a graph node removal, also removes the edges attached to the node: `remove with <Event> key <expression> detach`. Not valid on an edge.',
    identified: 'On a graph edge, `identified by <property>` lets several edges of one type join the same two nodes; each is identified by that property as well.',
    reducer: 'Builds a read model from events with imperative code — `reducer <Name> => <ReadModel>` with an `on <EventType>` rule per event. Use it when a projection cannot express the transition.',
    specification: 'Given/when/then acceptance criteria for a slice: prior events and state, the command, query or appended event under test, and the events, state, results, errors or denials that follow.',
    dialog: 'A dialog opened over the shell, or with `dialog template` a reusable dialog shape.',
    form: 'A form bound to a command — `form <Name> for <Command>` with a `field` per input.',
    slot: 'A slot is a region content is placed in. A plain line of a layout or template declares one: `<name> [page|pane|panel] [routed [by <param>]] [primary] [optional]`. `slot <name>` in a template or component declares a slot filled recursively, `slot <name>` under `navigate to` opens the destination in it, and `destination slot <name>` sends a navigation item there. Screenplay 6 renamed these from `outlet`; run `screenplay migrate --from 5 --to 6`.',
    routed: 'Marks a slot as routed - what it shows is part of the address. `routed by <param>` names the route parameter it is addressed by: `detail pane routed by sku optional`.',
    contribute: 'Adds to an outlet from any module or feature — `contribute to <outlet>` with `navigate to`, `label` and `order` for a navigation entry, or item lines of the outlet\'s kind: `button`, `group`, `filter`, `tab`, `stat` or `item`.',
    outlet: 'An item list a layout or template offers — `outlet <name> of actions|filters|tabs|stats|navigation [for item|for screen] [in <slot>]` with `default` items. A module, feature or screen writes `outlet <name> inherits|extends|overrides`, may `hide <id>` an inherited item and place its own `before <id>` or `after <id>`. Screenplay 6 turned `navigation topbar|sidebar`, a slot\'s `contributes` and a feature `toolbar` into outlets; run `screenplay migrate --from 5 --to 6`.',
    default: 'An item an outlet shows unless a lower level changes it — `default <id> title "…" …`, in the outlet\'s item form without the item\'s keyword. In a `design system`, `default theme <Name>` names the theme an application uses unless its `ui profile` picks another.',
    hide: 'Drops an inherited outlet item — `hide <id>` under `outlet <name> extends|overrides`.',
    group: 'A menu of buttons in an actions outlet — `group <id> title "…" [icon <name>]` with `button` lines under it.',
    tab: 'A tab in a tabs outlet — `tab <id> title "…" [shows <Screen>]` shows a screen in the slot the outlet is `in`.',
    stat: 'A figure in a stats outlet — `stat <id> title "…" [value from <Query>.<field>]` reads a field of a single-result query.',
    sets: 'Binds a filter to a query parameter — `filter <id> title "…" sets <Query>.<param>`.',
    shows: 'The screen a tab shows — `tab <id> title "…" shows <Screen>`. In a slice, `shows event|readmodel <Name>` draws a linked copy of a declaration.',
    button: 'A toolbar or actions outlet button that invokes a State Change slice — `button <id> title "…" slice <Module>.<Feature>.<Slice> [emphasis primary|secondary|quiet] [icon <name>] [runs close|submit|refresh] [for item|for screen] [opens dialog|drawer|in slot <name>]`. A button linked to a slice is a hook: it opens the slice\'s screen in its first fit the page has free, or where `opens` says; a `runs` line under it issues the command without a form. `enabled when <condition>` and `confirm "…"` go under it too.',
    sketch: 'A screen sketch file — `sketch <path>`, relative to the model root.',
    mockup: 'An HTML mockup page of a screen — `mockup <path>`.',
    image: 'A screen image — `image <path>`: PNG, JPG, GIF, SVG or WebP.',
    fits: 'Where a slice\'s screen fits, in order of preference — `fits dialog, drawer, pane` (also `panel`, `page`). A hook that names no place opens the screen in the first fit the page has free; `opens in slot` needs a slot whose role the screen fits.',
    drawer: 'A place a slice\'s screen fits or a hook opens it — `fits drawer` on a screen, `opens drawer` on a button.',
    opens: 'How a hook opens its slice — `opens dialog`, `opens drawer` or `opens in slot <name>` on a button. Without it the hook opens the slice\'s screen in its first fit the page has free.',
    enabled: 'When a button or toolbar item can be pressed — `enabled when <condition>` under it, in the guarded-action condition grammar; `item.<field>` reads the selected row.',
    show: 'What a template slot shows — `show <Screen> by <param> from <element>.selection` shows another screen for the row a table or component on this screen has selected.',
    selection: 'The row a table or component has selected — `show <Screen> by <param> from <element>.selection`.',
    choose: 'A form field that is a picker — `choose from query <Query> show <field>` under `field <property>`. A field whose concept keys a read model one list query returns is a picker without it.',
    navigation: 'An outlet kind — `outlet <name> of navigation` holds `item` destinations and, on a layout, the application\'s `logo`. Screenplay 5\'s `navigation topbar|sidebar` is an error since Screenplay 6; run `screenplay migrate --from 5 --to 6`.',
    theme: 'A named theme — it `implements` a design system, supplies a `palette` and `values` for its tokens per mode, and names the component packages it is `compatible with`.',
    design: 'A design system — `design system <Name>` declares the vocabulary of an application\'s look: its `modes`, the `default theme`, `tokens` by category, `components` with parts and variants, `words` and contrast `rules`. A theme `implements` it and supplies the values.',
    modes: 'In a `design system`, `modes light, dark` names the modes a theme supplies color values for.',
    tokens: 'In a `design system`, the `tokens` block lists design tokens under a category (`color`, `space`, `size`, `radius`, `border`, `shadow`, `font`, `type`, `motion`, `opacity`, `z`). A token is addressed as `category.token`.',
    components: 'In a `design system`, the `components` block declares each component with its `parts` and `variant`s, each part set to a `category.token`.',
    words: 'In a `design system`, the `words` block holds `voice` and `naming` entries, each `key = "text"`.',
    voice: 'In a design system `words` block, `voice` holds `key = "text"` entries describing how the product speaks.',
    naming: 'In a design system `words` block, `naming` holds `key = "text"` entries describing how things are named.',
    rules: 'In a `design system`, the `rules` block holds `contrast <part> on <part> at least <ratio>` rules a theme must satisfy.',
    contrast: 'In a design system `rules` block, `contrast <part> on <part> at least <ratio>` requires a minimum contrast ratio between two parts (such as `text` on `background`).',
    palette: 'In a `theme`, the `palette` block names raw values — `<name> = "value"` — that token values can refer to as `palette.<name>`.',
    values: 'In a `theme`, the `values` block sets each design token for every mode — `category.token = "value"`, `palette.<name>` or another token. A mode block (such as `light` or `dark`) sets mode-specific values.',
    implements: 'In a `theme`, `implements <DesignSystem>` binds the theme to the design system whose tokens it supplies values for.',
    parts: 'In a design system component, `parts text, background, ...` lists the parts a variant can style: `text`, `background`, `border`, `radius`, `height`, `padding`, `shadow`, `font`.',
    variant: 'In a design system component, `variant <name>` sets each part to a `category.token`; nested `state <name>` blocks (`default`, `hover`, `focus`, `active`, `disabled`, `selected`) override parts for a state.',
    compatible: 'In a `theme`, `compatible with <Package>` names a component package the theme is compatible with.',
    sample: 'Sample data — `sample data <Name>` declares a pack of demo rows per `shape` that a design surface or preview shows instead of a backend. Design and preview time only; it never reaches backend or production output. The application picks its active pack once, in the `ui profile`.',
    active: 'The active sample data pack of the whole application, chosen once in the `ui profile` `sample data` block — one declared in the document, or `blueprint <id>` for one a blueprint ships.',
    bind: 'Binds one read model to a sample data pack — `bind <ReadModel> to <pack>` — a rare override of the active pack for that read model only.',
    maps: 'Maps a sample data shape to the read model it supplies rows for — `shape <Shape> maps to <ReadModel>` — where the names differ.',
    row: 'One row of a sample data shape: `<field> = <literal>` lines, each field a property of the read model.',
    locale: 'The BCP 47 locale tag of a sample data pack, such as `nb-NO`.',
    shape: 'In sample data, the shape a set of rows is for; it matches the read model of the same name or the one a `ui profile` maps it to.',
    root: 'In a `ui profile`, `root template [blueprint <Blueprint>] <Name> [version "<range>"]` names the template the whole application is drawn in, with `option <name> <value>` lines for what the shell exposes.',
    appearance: 'In a `ui profile`, the `appearance` block holds `color scheme light|dark|system`. `accent`, `corners` and `font` are deprecated - the theme supplies them (PLAY0929).',
    corners: 'In a `ui profile` `appearance` block, `corners sharp|default|round` is how rounded the application\'s corners are. Deprecated (PLAY0929): the theme supplies it.',
    font: 'In a `ui profile` `appearance` block, `font <font id>` is the application\'s font, an id from Scene\'s font catalog (`inter`, `ibm-plex-sans`, `source-serif-4`, `system-ui`). Deprecated (PLAY0929): the theme supplies it.',
    logo: 'In a `ui profile` `identity` block, `logo initials "<AB>"`, `logo icon <icon>` or `logo image "<data URI>"` is the mark the application wears.',
    accent: 'In a `ui profile` `appearance` block, `accent "<#hex>"` is the accent colour of the application. Deprecated (PLAY0929): the theme supplies it.',
    scheme: 'In a `ui profile` `appearance` block, `color scheme light|dark|system` is the colour scheme of the application.',
    screens: 'In a `ui profile`, `new screens use template [blueprint <Blueprint>] <Name>` is the template a new screen starts from.',
    ui: 'A UI profile — `ui profile <Name>` binds a target platform and size to a layout, theme and packages.',
    behavior: 'A named interaction wiring of `on <interaction>` handlers, attached to a screen, form or dialog with `uses`.',
    system: 'An application-scoped external system. It declares `ability` blocks, which say what the system can be asked to do; operations `uses` it.',
    extension: '`extension "<package>" [version <v>]` under a `system`: the extension that realizes it. Realization metadata outside the executable model.',
    setting: '`setting <name> from secret <Name>` or `setting <name> = <literal>` under a `system`. A setting the model does not mention is read from `systems.<System>.<setting>`. A literal is for non-secret settings only.',
    display: '`display name "<text>"` in an extension `contract.play`: the name a person sees. Required in a contract.',
    requires: '`requires stage "<range>"`, `requires screenplay "<range>"`, `requires platform <name>` or `requires runtime <name> <version>` in an extension contract: what the package needs.',
    signal: '`signal.<value>` in `with <input> from signal.<value>` under an `on <signal>` of an extension component: a value the signal carries. The signal is one the extension contract `raises`.',
    placeholder: '`placeholder "<path>"` under a contract `component`: a static HTML file design tools draw in place of the component. No script and no external references.',
    frontend: '`frontend "<path>"` in an extension contract: the package-relative entry point of the frontend.',
    backend: '`backend runtime <name> <version> assembly "<file>"` in an extension contract: the backend tier.',
    activation: '`activation always` or `activation on demand [idle after <n> <unit>]` under a `system`: overrides the extension contract\'s default.',
    ability: '`ability <Name> [safe | idempotent | once]` under a `system`: typed inputs, an optional `returns` block, named `outcome`s, optional `answers later` and an optional implementation. `safe` has no effect and retries freely, `idempotent` repeats with the same key, `once` (the default) is never retried.',
    answers: '`answers later` marks an ability whose answer arrives after the invocation returns.',
    eventsource: 'An application-owned event source with nested streams.',
    operation: 'A reusable operation intent that uses one external system.',
    no: 'A keyed absence assertion: `then no readmodel <View> for <key>`.',
    arguments: 'The values supplied to a query asserted by `then query`.',
    result: 'One expected result - `then result [exactly]` after `when query`, or a `result` block inside `then query`. Repeat it to assert several results in authored order.',
    clock: 'The instant a specification happens at - `given clock "2026-10-05T08:00:00Z"` fixes when everything occurs, including every generated pattern date segment at that same UTC instant. Without given clock, generation fixtures check date digit widths only, never the wall clock. `when clock "<instant>"` is the clock reaching it, as the action. ESM v37 clock-using command specifications need an explicit UTC given clock and given time zone.',
    exactly: 'Requires every property to match, rather than only the ones asserted - on `then readmodel`, `then query` and `then result`.',
    file: 'Delegates the implementation to an external file; the Screenplay contract stays visible.',
    key: 'Trailing modifier on a required top-level read-model property. Explicit keys replace inference. Several scalar key properties identify one instance by named parts. Supply every part in a single-instance query by block and in projection key blocks; list queries can use equality filters.',
    stream: 'On a command event production, replaces the whole command route for that event. Other productions keep the command route. Admitted by ESM v10.',
    by: 'Introduces one identifying parameter or a block of at least two named key parts. Reads use part = source; queries use part Type.',
    via: 'Connects screen data to the query that supplies it.',
    filter: 'An optional query filter parameter.',
    on: 'The event a constraint applies to, the day a schedule narrows to, or a widget interaction such as `on row-click`. Under an extension component, `on <signal>` handles a signal its contract `raises`, and `on <System>.<Trigger>` an extension trigger.',
    component: '`component <System>.<Component> <name>` on a screen places a component the system\'s extension provides, checked against its contract: `property` lines name its properties and `on <signal>` handles what it raises. In a contract, `component <Name>` declares one.',
    message: 'The validation message reported when the rule fails.',
    matches: 'Searches text using the portable flagless JavaScript match dialect, or `email`. Use ^ and $ for the whole input. Exact Studio text-rule lookarounds warn with PLAY0787 and lower to ordinal rules; other lookarounds, backreferences and refused constructs report PLAY0699; patterns have at most 1000 source code units and 3000 expanded nodes, including optional, loop and alternative choice points.',
    all: 'Applies a comparison to every element of a collection.',
    max: 'Maximum length or value.',
    min: 'Minimum length or value.',
    length: 'Constrains the exact length of a value.',
    today: 'ESM v37 calendar date. Supports integral day offsets such as today - 7 days, not hours or minutes. A property named today remains a path. Specifications using it need given clock and given time zone.',
    now: 'ESM v37 instant, with integral day/hour/minute offsets. date of now + 2 hours applies the duration before converting to the selected calendar date. Only command conditions and command property rules admit clock operands; not concepts, reactions, read paths or arbitrary context paths.',
    date: 'date of converts a DateTime command property or a clock operand to the selected calendar date. ESM v37 command conditions; property rules accept date of today or date of now, not date of a property.',
    of: 'date of converts to the selected calendar date after applying a clock offset (ESM v37).',
    calendar: 'ESM v37 command calendar: calendar "<IANA id>" or calendar from $context.timeZone or a member declared in the context block; other context paths remain refused. Selection order: command calendar, scenario zone, execution-context zone, application default. A property named calendar remains a property.',
    zone: 'ESM v37 application time zone "<IANA id>" or time zone configurable default "<IANA id>"; a specification pins given time zone "<IANA id>" and given clock. Selection order: command calendar, scenario zone, execution-context zone, application default.',
    empty: 'Ends a structured value header for an object without members: `<name> empty`. Also used with `not empty` — text needs a non-whitespace character; null, empty and whitespace-only text fail. Unicode White_Space is U+0009–U+000D, U+0020, U+0085, U+00A0, U+1680, U+2000–U+200A, U+2028, U+2029, U+202F, U+205F and U+3000 (not U+FEFF). Collections need at least one element. Applies to concept and command rules in every ESM version; no trimming. Identity text is unchanged: whitespace is a value.',
    not: 'Negates a validation condition, as in `not empty`.',
    and: 'Both conditions must hold.',
    or: 'Either condition may hold.',
    csharp: 'An inline C# block whose opening fence is ```csharp.',
    java: 'An opaque inline Java block whose opening fence is ```java. For Java-capable targets such as Axon; the Cratis target refuses Java bodies.',
    sql: 'An inline SQL block between triple backticks — a query performer written against a relational store.',
    typescript: 'An inline TypeScript block between triple backticks.',
    react: 'An inline React/TSX block; receives the surrounding data contract as `Props`.',
    html: 'An inline static HTML block.',
    StateChange: 'Slice type — a command → events flow; something that changes the system.',
    StateView: 'Slice type — a query + projection + screen; something that reads the system.',
    Automation: 'Slice type — a reaction or reducer; something that runs when something happens.',
    Translate: 'Slice type — a capture; converts external data into events.',
    Uuid: 'Primitive type — a universally unique identifier. ESM v28 admits == and != between Uuid values (or concepts over Uuid) in command require and produces when; two concepts must be the same concept, and a literal must be canonical lowercase hyphenated. Ordering, optional operands, validation rules, concept rules and reaction where stay refused.',
    String: 'Primitive type — a string of characters.',
    Int: 'Primitive type — an integer number.',
    Decimal: 'Primitive type — a decimal number.',
    Bool: 'Primitive type — true or false.',
    Date: 'Primitive type — a calendar date without a time zone. ESM v26 admits all six comparisons in command require, produces when and command/property rules. Conditions use required same-primitive command properties or a literal; rules use literals only. Canonical literals use yyyy-MM-dd. ESM v37 also admits today/now offsets and date of in command conditions and property rules. Concept rules, reaction where, read paths and arbitrary context paths stay refused.',
    DateTime: 'Primitive type — a date and time. ESM v26 command comparisons order UTC instants at tick precision, including equality across offsets. Compared input requires an explicit offset or Z before any rule runs; literals canonicalize to UTC with seven fractional digits and Z. Targets without tick precision refuse comparisons; client validators omit date ordering. Other equality stays ordinal.',
    Enum: 'An enumeration concept with named members. Members may all declare unique int32 numbers (draft = 1) or all omit them (zero-based positions). Never renumber or reuse a published number. Non-positional numbers select executable model (ESM) v12; consumers must explicitly admit v12. Specifications still name members.',
};

// What the words of a specification's steps mean there - where 'trigger', 'capture' and 'query' name what the
// scenario exercises rather than declare one.
export const specificationKeywordDocs: Record<string, string> = {
    parameter: 'Declares a required typed case value: `parameter <name> <Type>`. Every case assigns it once. `optional` permits literal null but supplies no default.',
    case: 'One named complete row of a specification table. `case.<parameter>` substitutes a whole value after example overrides; each row runs as `<Specification>_<Case>`.',
    caller: '`given caller` states an explicit identity; `given caller as <Persona>` synthesizes an authenticated deterministic witness of the persona, with no body. Leftmost buildable policy alternatives are significant.',
    clock: keywordDocs.clock,
    redelivered: keywordDocs.redelivered,
    trigger: '`when trigger <Trigger>` - an application trigger fires, as the action, with the values on the lines beneath it.',
    capture: '`given capture <Capture>` - a record the capture\'s source held before; `when capture <Capture>` - the record it sees now, as the action. The fields go on the lines beneath.',
    query: '`when query <Query>` performs the query with arguments beneath it; assert returned rows with `then result` or genuine absence with `then no result`. From ESM v18, one actionless query with `then error` asserts exactly Validation and no other outcome. This also works with `then query` and an arguments block, without a result block.',
    events: '`then no events` - asserts the action appended no events, also after `when append`, where it means no reaction appended anything. Executable from ESM v17. Cannot accompany event, event-order, error or denial expectations.',
    result: '`then result [exactly]` - one result the query performed by `when query` returns, in order; `then no result` - it returns nothing.',
};

export const attributeDocs: Record<string, string> = {
    pii: 'personal data (GDPR Art. 4(1)); renders Chronicle [PII]. Bare suffix marker; @pii is deprecated (PLAY0565). Selects executable model (ESM) v13; consumers must explicitly admit it. Cannot classify identity or enum concepts. An event with personal values and an explicit subject mark refuses binding (PLAY0268) until lineage is admitted.',
    personal: 'Alias of pii: personal data (GDPR Art. 4(1)); renders Chronicle [PII]. No diagnostic; canonical printing writes pii. Selects executable model (ESM) v13, like pii.',
    secret: 'Operational secret, not personal data: encrypted at rest without erasure and withheld from causation. Provider mapping: [Encrypted] + [NotAudited], or [PII] only with pii. Selects executable model (ESM) v13; reference outcomes are unchanged. Cannot classify identity (PLAY0515) or enum concepts. Explicit scope is omitted next to pii. An event combining secret scope subject with an explicit subject mark refuses binding (PLAY0268).',
    sensitive: 'Deprecated spelling of secret (PLAY0565); repair to bare secret. Operational secret, not GDPR Art. 9 special-category data.',
};

